INSERT INTO `everlake_build_stage` (`n`, `ID`, `txt`) VALUES
(1, 96377, '<It occurs to you that Shaw''s right-hand goblin might be interested to see the documents you''ve recovered from Westfall. Ask him if any of these documents make any sense to him.>');
DELETE s FROM `everlake_build_stage` s WHERE EXISTS (SELECT 1 FROM `quest_request_items` x WHERE x.`ID` = s.`ID`) OR NOT EXISTS (SELECT 1 FROM `quest_template` q WHERE q.`ID` = s.`ID`);
INSERT INTO `quest_request_items` (`ID`, `CompletionText`, `VerifiedBuild`) SELECT s.`ID`, s.`txt`, 0 FROM `everlake_build_stage` s ORDER BY s.`n`;
INSERT IGNORE INTO `everlake_import_rows` (`tbl`, `k1`, `file`, `note`) SELECT 'quest_request_items', s.`ID`, '2026_11_20_25_world_everlake_quests_questiedb_givers.sql', 'seen-live: icyveins:addon_dialog' FROM `everlake_build_stage` s;
